class Solution {
public:
    int shortestDistance(vector<vector<int>>& maze, vector<int>& start, vector<int>& destination) {
        int m = maze.size(), n = maze[0].size();
        const int dr[4] = {1, -1, 0, 0};
        const int dc[4] = {0, 0, 1, -1};
        vector<vector<int>> dist(m, vector<int>(n, INT_MAX));
        using State = tuple<int, int, int>;
        priority_queue<State, vector<State>, greater<State>> pq;
        dist[start[0]][start[1]] = 0;
        pq.push(make_tuple(0, start[0], start[1]));
        while (!pq.empty()) {
            int steps, r, c;
            tie(steps, r, c) = pq.top();
            pq.pop();
            if (steps != dist[r][c]) {
                continue;
            }
            for (int d = 0; d < 4; ++d) {
                int nr = r, nc = c, count = 0;
                while (nr + dr[d] >= 0 && nr + dr[d] < m &&
                       nc + dc[d] >= 0 && nc + dc[d] < n &&
                       maze[nr + dr[d]][nc + dc[d]] == 0) {
                    nr += dr[d];
                    nc += dc[d];
                    ++count;
                }
                if (steps + count < dist[nr][nc]) {
                    dist[nr][nc] = steps + count;
                    pq.push(make_tuple(dist[nr][nc], nr, nc));
                }
            }
        }
        int answer = dist[destination[0]][destination[1]];
        return answer == INT_MAX ? -1 : answer;
    }
};
